public final class Order {
    private final Map<String, Object> props = new HashMap<>();
    public void set(String name, Object value) { props.put(name, value); }
    public Optional<Object> get(String name)   { return Optional.ofNullable(props.get(name)); }
    public boolean has(String name)            { return props.containsKey(name); }
    public void remove(String name)            { props.remove(name); }
    public Set<String> propertyNames()         { return props.keySet(); } // discoverability
}

